async function yalcaSignUp(e,a,r){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente. Veja o guia de configuração."};const{data:n,error:t}=await supabaseClient.auth.signUp({email:e.trim(),password:a,options:{data:{store_name:r||""}}});if(t)return{ok:!1,error:yalcaAuthErrorMessage(t)};if(!n.session)return{ok:!0,pendingEmailConfirmation:!0};const{error:s}=await supabaseClient.from("client_profiles").insert({email:e.trim(),store_name:r||""});return s?{ok:!1,error:"Conta criada, mas houve um erro ao registrar seu perfil: "+s.message}:{ok:!0,pendingEmailConfirmation:!1}}async function yalcaLogin(e,a){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente. Veja o guia de configuração."};const{data:r,error:n}=await supabaseClient.auth.signInWithPassword({email:e.trim(),password:a});return n?{ok:!1,error:yalcaAuthErrorMessage(n)}:{ok:!0,session:r.session}}async function yalcaIsLoggedIn(){if(!supabaseClient)return!1;const{data:e}=await supabaseClient.auth.getSession();return!!e.session}async function yalcaCurrentUser(){if(!supabaseClient)return null;const{data:e}=await supabaseClient.auth.getUser();return e.user||null}async function yalcaLogout(){supabaseClient&&await supabaseClient.auth.signOut()}async function yalcaRequireAuth(){return!!await yalcaIsLoggedIn()||(window.location.href="login.html",!1)}async function yalcaEnsureProfile(){const e=await yalcaGetOwnProfile();if(e)return e;const a=await yalcaCurrentUser();if(!a)return null;const{data:r,error:n}=await supabaseClient.from("client_profiles").insert({email:a.email,store_name:a.user_metadata&&a.user_metadata.store_name||""}).select().single();return n?null:r}async function yalcaUpdatePassword(e){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente."};const{error:a}=await supabaseClient.auth.updateUser({password:e});return a?{ok:!1,error:yalcaAuthErrorMessage(a)}:{ok:!0}}async function yalcaRequestPasswordReset(e){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente."};const{error:a}=await supabaseClient.auth.resetPasswordForEmail(e.trim(),{redirectTo:window.location.origin+window.location.pathname.replace(/login\.html$/,"dashboard.html")});return a?{ok:!1,error:yalcaAuthErrorMessage(a)}:{ok:!0}}async function yalcaGetOwnProfile(){const e=await yalcaCurrentUser();if(!e)return null;const{data:a,error:r}=await supabaseClient.from("client_profiles").select("*").eq("user_id",e.id).maybeSingle();if(r)throw new Error(r.message);return a}async function yalcaIsAdmin(){const e=await yalcaCurrentUser();if(!e)return!1;const{data:a,error:r}=await supabaseClient.from("admins").select("user_id").eq("user_id",e.id).maybeSingle();return!r&&!!a}function yalcaAuthErrorMessage(e){const a=e&&e.message?e.message:"";return a.includes("Invalid login credentials")?"E-mail ou senha incorretos.":a.includes("Email not confirmed")?"Este e-mail ainda não foi confirmado. Verifique sua caixa de entrada.":a.includes("User already registered")?"Já existe uma conta com este e-mail. Tente entrar em vez de criar uma nova conta.":a.includes("Password should be at least")?"A senha precisa ter pelo menos 6 caracteres.":a.includes("New password should be different")?"A nova senha precisa ser diferente da atual.":a.includes("rate limit")||a.includes("Too many")?"Muitas tentativas seguidas. Espere um minuto e tente de novo.":a.includes("Failed to fetch")||a.includes("NetworkError")?"Sem conexão com o servidor. Verifique sua internet e tente de novo.":a||"Não foi possível concluir. Tente novamente em instantes."}